// src/lib/api/arp-client.ts
import axios from 'axios';

export const arpApiClient = {
  getValidationData: async () => {
    const { data } = await axios.get('/api/v1/validation/arp-v3');
    return data;
  },

  requestAssetAccess: async (assetId: string, payload: { email: string; reason: string }) => {
    const { data } = await axios.post(`/api/v1/assets/${assetId}/request-access`, payload);
    return data;
  },

  getPipelineStatus: async () => {
    const { data } = await axios.get('/api/v1/pipeline/status');
    return data;
  },
};
```

