// pathway/PathwayNode.tsx
export function PathwayNode({ node, isSelected, isHovered, onClick, onHover }) {
  const size = node.type === 'enzyme' ? 48 : 36;
  const color = node.isTarget ? '#3B82F6' : node.type === 'enzyme' ? '#8B5CF6' : '#6B7280';

  // Expression fold change → opacity/brightness
  const expressionIntensity = node.expressionFoldChange 
    ? Math.min(node.expressionFoldChange / 5, 1) 
    : 0.3;

  return (
    <g
      transform={`translate(${node.x}, ${node.y})`}
      onClick={onClick}
      onMouseEnter={onHover}
      onMouseLeave={() => onHover(null)}
      className="cursor-pointer"
    >
      {/* Pulse animation for targets */}
      {node.isTarget && (
        <circle r={size * 0.8} fill="none" stroke={color} strokeWidth="1" opacity="0.3">
          <animate attributeName="r" from={size * 0.6} to={size * 1.2} dur="2s" repeatCount="indefinite" />
          <animate attributeName="opacity" from="0.4" to="0" dur="2s" repeatCount="indefinite" />
        </circle>
      )}

      {/* Main node circle */}
      <circle
        r={size / 2}
        fill={`${color}${Math.round(expressionIntensity * 255).toString(16).padStart(2, '0')}`}
        stroke={isSelected ? '#FFFFFF' : color}
        strokeWidth={isSelected ? 2 : 1}
        filter={node.isTarget ? 'url(#targetGlow)' : undefined}
      />

      {/* Inhibition icon overlay */}
      {node.inhibitionStatus === 'active' && (
        <g transform={`translate(${size/4}, ${-size/4})`}>
          <line x1="-4" y1="-4" x2="4" y2="4" stroke="#EF4444" strokeWidth="2" />
          <line x1="4" y1="-4" x2="-4" y2="4" stroke="#EF4444" strokeWidth="2" />
        </g>
      )}

      {/* Label */}
      <text
        y={size / 2 + 16}
        textAnchor="middle"
        fill={isHovered ? '#FFFFFF' : '#A3A3A3'}
        fontSize="11"
        fontFamily="Inter, sans-serif"
        fontWeight={node.isTarget ? 600 : 400}
      >
        {node.label}
      </text>
    </g>
  );
}

// hooks/usePathwayInteraction.ts
export function usePathwayInteraction() {
  const [transform, setTransform] = useState(new DOMMatrix());
  const [selectedNode, setSelectedNode] = useState<PathwayNode | null>(null);
  const [hoveredNode, setHoveredNode] = useState<PathwayNode | null>(null);
  const [tooltipPosition, setTooltipPosition] = useState({ x: 0, y: 0 });

  const isDragging = useRef(false);
  const dragStart = useRef({ x: 0, y: 0 });

  const handleWheel = useCallback((e: React.WheelEvent) => {
    e.preventDefault();
    const scaleFactor = e.deltaY > 0 ? 0.9 : 1.1;
    const newTransform = transform.translateSelf(0, 0)
      .scale(scaleFactor);
    setTransform(newTransform);
  }, [transform]);

  const handleNodeClick = useCallback((node: PathwayNode) => {
    setSelectedNode(prev => prev?.id === node.id ? null : node);
  }, []);

  const handleNodeHover = useCallback((node: PathwayNode | null) => {
    setHoveredNode(node);
    if (node) {
      setTooltipPosition({ x: node.x + 40, y: node.y - 20 });
    }
  }, []);

  return {
    transform,
    selectedNode,
    hoveredNode,
    tooltipPosition,
    handleWheel,
    handleNodeClick,
    handleNodeHover,
  };
}
