export function TargetHeatmap() {
  const [selectedMetric, setSelectedMetric] = useState<'rnaExpr' | 'proteinExpr' | 'dependency'>('rnaExpr');
  const [selectedTarget, setSelectedTarget] = useState<string | null>(null);

  // Fetch from ARP v3 API or static generated data
  const { data: multiOmicsResults, isLoading } = useAgentData<MultiOmicsResult[]>('MultiOmics');

  const matrix = useMemo(() => {
    if (!multiOmicsResults) return [];

    // Pivot: rows=tissues, columns=targets, values=selected metric
    const tissues = [...new Set(multiOmicsResults.map(r => r.data.tissue))];
    const targets = [...new Set(multiOmicsResults.map(r => r.data.target))];

    return tissues.map(tissue => ({
      tissue,
      cells: targets.map(target => {
        const result = multiOmicsResults.find(r => r.data.tissue === tissue && r.data.target === target);
        return {
          target,
          value: result ? getMetricValue(result.data.metrics, selectedMetric) : null,
          pValue: result?.data.metrics.rnaExpression.pValue,
          runId: result?.runId,
        };
      }),
    }));
  }, [multiOmicsResults, selectedMetric]);

  const colorScale = useMemo(() => {
    if (selectedMetric === 'dependency') {
      // CERES: lower = more dependent (red)
      return interpolateRgbBasis(['#2563EB', '#030303', '#EF4444']);
    }
    // Expression: higher = more upregulated (red)
    return interpolateRgbBasis(['#2563EB', '#030303', '#EF4444']);
  }, [selectedMetric]);

  return (
