    const params = new URLSearchParams(window.location.search);
    if (params.get('utm_source') === 'investor_deck') score.investor += 0.8;
    if (params.get('utm_campaign')?.includes('partner')) score.pharma_partner += 0.7;
    if (params.get('type') === 'data_request') score.researcher += 0.6;

    // Behavior signals (from localStorage)
    const behavior = JSON.parse(localStorage.getItem('bbt_behavior') || '{}');
    if (behavior.pagesViewed?.includes('/pipeline')) score.pharma_partner += 0.3;
    if (behavior.pagesViewed?.includes('/data-portal')) score.researcher += 0.4;
    if (behavior.downloads?.length > 0) score.investor += 0.2;

    // Determine segment
    const maxScore = Math.max(...Object.values(score));
    const detectedSegment = (Object.keys(score) as VisitorSegment['type'][])
      .find(key => score[key] === maxScore) || 'general';

    setSegment({
      type: detectedSegment,
      confidence: Math.min(maxScore, 1),
      signals
    });

    // Store for analytics
    localStorage.setItem('bbt_segment', JSON.stringify({
      segment: detectedSegment,
      confidence: maxScore,
      timestamp: Date.now()
    }));
  }, []);

  return segment;
}

export default function DynamicHero() {
  const segment = useVisitorSegment();
  const config = HERO_CONFIGS[segment.type];
  const [isVisible, setIsVisible] = useState(false);

  useEffect(() => {
    // Stagger animation for credibility
