};

export default function ProgressiveLeadForm({ 
  magnetId, 
  segment 
}: { 
  magnetId: string; 
  segment: VisitorSegment['type'] 
}) {
  const [step, setStep] = useState(1);
  const [formData, setFormData] = useState<FormData>({ email: '' });
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [isComplete, setIsComplete] = useState(false);

  const magnet = LEAD_MAGNETS.find(m => m.id === magnetId);
  if (!magnet) return null;

  // Check if already downloaded
  const existingLead = useExistingLead(magnetId);
  if (existingLead) return <InstantDownload magnet={magnet} />;

  const currentFields = STEP_FIELDS[step];
  const totalSteps = Math.ceil(magnet.requiredFields.length / 2);

  const handleSubmit = async () => {
    setIsSubmitting(true);

    // Track conversion
    await trackEvent('lead_capture', {
      magnet_id: magnetId,
      gate_level: magnet.gateLevel,
      segment,
      step,
      fields_completed: Object.keys(formData).filter(k => formData[k as keyof FormData]).length
    });

    // Submit to backend
    const response = await fetch('/api/leads', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({
        ...formData,
        magnet_id: magnetId,
        segment,
        source: 'progressive_form',
        timestamp: new Date().toISOString()
      })
    });

    if (response.ok) {
