          disabled={!validateStep(step, formData) || isSubmitting}
          className="bg-bbt-blue text-white px-6 py-2.5 rounded-lg font-medium hover:bg-bbt-blue-dark disabled:opacity-50 disabled:cursor-not-allowed flex items-center gap-2"
        >
          {isSubmitting ? (
