**What to code:** Client-side analytics that tracks segment assignment, CTA engagement, and lead magnet conversions.

**Expected Impact:** Data-driven optimization loop for future iterations

```typescript
// src/lib/analytics/segmentTracker.ts

interface AnalyticsEvent {
  event: string;
  properties: Record<string, any>;
  timestamp: string;
  session_id: string;
}

class SegmentTracker {
  private sessionId: string;
  private queue: AnalyticsEvent[] = [];
  private flushInterval: NodeJS.Timeout;

  constructor() {
    this.sessionId = this.getOrCreateSession();
    this.flushInterval = setInterval(() => this.flush(), 5000);
  }

  private getOrCreateSession(): string {
    const stored = sessionStorage.getItem('bbt_session_id');
    if (stored) return stored;
    const id = `sess_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
    sessionStorage.setItem('bbt_session_id', id);
    return id;
  }

  trackPageView(path: string, segment: string) {
    this.enqueue({
      event: 'page_view',
      properties: { path, segment },
      timestamp: new Date().toISOString(),
      session_id: this.sessionId
    });
  }

  trackCTA(ctaId: string, segment: string, location: string) {
    this.enqueue({
      event: 'cta_click',
      properties: { cta_id: ctaId, segment, location },
      timestamp: new Date().toISOString(),
      session_id: this.sessionId
    });
  }

  trackLeadCapture(magnetId: string, gateLevel: number, segment: string, fieldsCompleted: string[]) {
    this.enqueue({
      event: 'lead_capture',
      properties: { 
        magnet_id: magnetId, 
        gate_level: gateLevel, 
        segment, 
        fields_completed: fieldsCompleted 
      },
      timestamp: new Date().toISOString(),
      session_id: this.sessionId
    });
  }

  trackPublicationView(publicationId: string, expanded: boolean) {
    this.enqueue({
      event: 'publication_interaction',
      properties: { publication_id: publicationId, expanded },
      timestamp: new Date().toISOString(),
      session_id: this.sessionId
    });
  }

  private enqueue(event: AnalyticsEvent) {
    this.queue.push(event);
    if (this.queue.length >= 10) this.flush();
  }

  private async flush() {
    if (this.queue.length === 0) return;

    const batch = [...this.queue];
    this.queue = [];

    try {
      await fetch('/api/analytics/batch', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ events: batch })
      });
    } catch (e) {
      // Re-queue on failure
      this.queue = [...batch, ...this.queue];
    }
  }

  destroy() {
    clearInterval(this.flushInterval);
    this.flush();
  }
}

export const analytics = new SegmentTracker();
