// types/visitor.ts
export type VisitorRole = 'scientist' | 'investor' | 'regulator' | 'partner' | 'unknown';

export interface VisitorProfile {
  role: VisitorRole;
  confidence: number;
  signals: DetectionSignal[];
  detectedAt: Date;
  contentVariant: ContentVariant;
}

export interface DetectionSignal {
  source: 'utm' | 'referrer' | 'behavior' | 'session';
  indicator: string;
  weight: number;
}

export type ContentVariant = 'science' | 'pipeline' | 'regulatory' | 'investor' | 'default';

// lib/visitor-detection.ts
export class VisitorDetector {
  private readonly UTM_SIGNALS: Record<string, VisitorRole> = {
    'source=ncbi': 'scientist',
    'source=pubmed': 'scientist',
    'source=nature': 'scientist',
    'source=crunchbase': 'investor',
    'source=sec.gov': 'regulator',
    'source=fda.gov': 'regulator',
    'campaign=series_a': 'investor',
    'campaign=pipeline_review': 'partner',
  };

  private readonly REFERRER_SIGNALS: Record<string, VisitorRole> = {
    'google.com': 'scientist', // weighted lower, refined by behavior
    'scholar.google.com': 'scientist',
    'bioRxiv.org': 'scientist',
    'pitchbook.com': 'investor',
    'sequoiacap.com': 'investor',
    'fda.gov': 'regulator',
    'ema.europa.eu': 'regulator',
  };

  private readonly BEHAVIOR_SIGNALS: Record<string, VisitorRole> = {
    '/science/dgat1-mechanism': 'scientist',
    '/science/yars2-pathway': 'scientist',
    '/pipeline': 'investor',
    '/investors': 'investor',
    '/regulatory/fda-submissions': 'regulator',
    '/compliance': 'regulator',
  };

  detect(initialSignals?: Partial<DetectionSignal[]>): VisitorProfile {
    const signals: DetectionSignal[] = [];

    // Layer 1: UTM parameters (highest confidence)
    signals.push(...this.detectUTMSignals());

    // Layer 2: Referrer domain
    signals.push(...this.detectReferrerSignals());

    // Layer 3: Behavioral signals (if session data exists)
    if (initialSignals) signals.push(...initialSignals);

    return this.classifyProfile(signals);
  }

  private detectUTMSignals(): DetectionSignal[] {
    const params = new URLSearchParams(window.location.search);
    const signals: DetectionSignal[] = [];

    for (const [key, role] of Object.entries(this.UTM_SIGNALS)) {
      const [param, value] = key.split('=');
      if (params.get(param) === value) {
        signals.push({
          source: 'utm',
          indicator: key,
          weight: 0.9, // High confidence for explicit UTM
        });
      }
    }
    return signals;
  }

  private detectReferrerSignals(): DetectionSignal[] {
    const referrer = document.referrer;
    if (!referrer) return [];

    const signals: DetectionSignal[] = [];
    for (const [domain, role] of Object.entries(this.REFERRER_SIGNALS)) {
      if (referrer.includes(domain)) {
        signals.push({
          source: 'referrer',
          indicator: domain,
          weight: 0.7,
        });
      }
    }
    return signals;
  }

  private classifyProfile(signals: DetectionSignal[]): VisitorProfile {
    if (signals.length === 0) {
      return {
        role: 'unknown',
        confidence: 0,
        signals: [],
        detectedAt: new Date(),
        contentVariant: 'default',
      };
    }

    // Weighted scoring by role
    const roleScores: Record<VisitorRole, number> = {
      scientist: 0,
      investor: 0,
      regulator: 0,
      partner: 0,
      unknown: 0,
    };

    for (const signal of signals) {
      const role = this.UTM_SIGNALS[signal.indicator] || 
                   this.REFERRER_SIGNALS[signal.indicator] ||
                   this.BEHAVIOR_SIGNALS[signal.indicator];
      if (role) {
        roleScores[role] += signal.weight;
      }
    }

    const topRole = (Object.entries(roleScores)
      .sort(([,a], [,b]) => b - a)[0][0]) as VisitorRole;

    const totalScore = Object.values(roleScores).reduce((a, b) => a + b, 0);
    const confidence = totalScore > 0 ? roleScores[topRole] / totalScore : 0;

    const VARIANT_MAP: Record<VisitorRole, ContentVariant> = {
      scientist: 'science',
      investor: 'investor',
      regulator: 'regulatory',
      partner: 'pipeline',
      unknown: 'default',
    };

    return {
      role: topRole,
      confidence: Math.min(confidence, 1),
      signals,
      detectedAt: new Date(),
      contentVariant: VARIANT_MAP[topRole],
    };
  }
}

