import { useState, useEffect } from 'react';
import { VisitorDetector } from '@/lib/visitor-detection';
import { ContentPersonalizer } from '@/lib/content-personalization';
import { ARPv3 } from '@/lib/arp-v3-client';
import { VisitorProfile, ContentConfig } from '@/types/visitor';

export function useVisitorProfile() {
  const [profile, setProfile] = useState<VisitorProfile | null>(null);
  const [content, setContent] = useState<ContentConfig | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const detector = new VisitorDetector();
    const detected = detector.detect();

    setProfile(detected);

    // Load personalized content
    const personalizer = new ContentPersonalizer(new ARPv3());
    personalizer.getContent(detected)
      .then(setContent)
      .finally(() => setLoading(false));
  }, []);

  return { profile, content, loading };
}

