interface PathwayNode {
  id: string;
  label: string;
  type: 'target' | 'enzyme' | 'metabolite' | 'pathway';
  x: number;
  y: number;
  status: 'active' | 'inhibited' | 'measured';
  data?: {
    expression?: number;
    pValue?: number;
    source?: string;
  };
}

interface PathwayEdge {
  from: string;
  to: string;
  type: 'activation' | 'inhibition' | 'metabolism';
  strength?: number;
}

interface PathwayDiagramProps {
  targetId: 'DGAT1' | 'YARS2';
  interactive?: boolean;
  showDataOverlay?: boolean;
