export function PathwayDiagram({ 
  targetId, 
  interactive = true,
  showDataOverlay = true 
}: PathwayDiagramProps) {
  const { data: pathwayData, loading } = useARPData({
    agent: 'MultiOmics',
    query: `${targetId} pathway network cancer metabolism`,
    format: 'pathway-graph',
  });

  if (loading) return <PathwaySkeleton />;

  const nodes: PathwayNode[] = transformToNodes(pathwayData, targetId);
  const edges: PathwayEdge[] = transformToEdges(pathwayData);

  return (
    <div className="relative w-full aspect-[16/10] bg-slate-950 rounded-xl overflow-hidden">
      {/* Background grid */}
      <svg className="absolute inset-0 w-full h-full opacity-10">
        <pattern id="grid" width="40" height="40" patternUnits="userSpaceOnUse">
          <path d="M 40 0 L 0 0 0 40" fill="none" stroke="currentColor" strokeWidth="0.5"/>
        </pattern>
        <rect width="100%" height="100%" fill="url(#grid)" />
      </svg>

      {/* Edges */}
      <svg className="absolute inset-0 w-full h-full">
        {edges.map((edge, i) => (
          <PathwayEdge 
            key={i} 
            edge={edge} 
            nodes={nodes}
            animated={interactive}
          />
        ))}
      </svg>

      {/* Nodes */}
      {nodes.map((node) => (
        <motion.div
          key={node.id}
          className={`absolute transform -translate-x-1/2 -translate-y-1/2 cursor-pointer
            ${node.type === 'target' ? 'z-20' : 'z-10'}
          `}
          style={{ left: `${node.x}%`, top: `${node.y}%` }}
          whileHover={interactive ? { scale: 1.15 } : {}}
          onClick={() => interactive && handleNodeClick(node)}
        >
          <PathwayNodeComponent node={node} showData={showDataOverlay} />
        </motion.div>
      ))}

      {/* Legend */}
      <div className="absolute bottom-4 left-4 flex gap-4 text-xs text-slate-400">
        <LegendItem type="target" label="Target" />
        <LegendItem type="enzyme" label="Enzyme" />
        <LegendItem type="metabolite" label="Metabolite" />
        <LegendItem type="inhibition" label="Inhibition" />
      </div>

      {/* Data source attribution */}
      <div className="absolute bottom-4 right-4 text-xs text-slate-500">
        Data: MultiOmics Agent v3.0 | Updated: {pathwayData?.timestamp}
      </div>
    </div>
  );
}

function PathwayNodeComponent({ node, showData }: { node: PathwayNode; showData: boolean }) {
  const styles = {
    target: 'bg-emerald-500/20 border-emerald-500 ring-2 ring-emerald-500/30',
    enzyme: 'bg-blue-500/20 border-blue-500',
    metabolite: 'bg-amber-500/20 border-amber-500',
    pathway: 'bg-slate-500/20 border-slate-500',
  };

  return (
    <div className={`relative px-3 py-2 rounded-lg border ${styles[node.type]}`}>
      <span className="text-sm font-medium text-white">{node.label}</span>

      {showData && node.data && (
        <div className="absolute -bottom-8 left-1/2 -translate-x-1/2 whitespace-nowrap">
