// lib/arp-v3-client.ts
import { AgentCache } from './agent-cache';

type AgentType = 'Literature' | 'MultiOmics' | 'VirtualScreen' | 'Design' | 'ADMET' | 'WetLab';

interface ARPRequest {
  agent: AgentType;
  query: string;
  format?: 'json' | 'pathway-graph' | 'audit-summary' | 'compound-list';
  params?: Record<string, unknown>;
  priority?: 'low' | 'normal' | 'high';
}

interface ARPResponse<T = unknown> {
  success: boolean;
  data: T;
  metadata: {
    agent: AgentType;
    query: string;
    timestamp: string;
    processingTime: number;
    confidence: number;
    cacheHit: boolean;
    version: string;
  };
}

class ARPv3Client {
  private baseUrl: string;
  private cache: AgentCache;
  private version = '3.0';

  constructor() {
    this.baseUrl = process.env.NEXT_PUBLIC_ARP_API_URL || '/api/arp';
    this.cache = new AgentCache({ ttl: 300000 }); // 5 min cache
  }

  async query<T = unknown>(request: ARPRequest): Promise<ARPResponse<T>> {
    // Check cache first
    const cacheKey = this.getCacheKey(request);
    const cached = this.cache.get<ARPResponse<T>>(cacheKey);
    if (cached) {
      return { ...cached, metadata: { ...cached.metadata, cacheHit: true } };
    }

    const response = await fetch(`${this.baseUrl}/query`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'X-ARP-Version': this.version,
      },
      body: JSON.stringify({
        ...request,
        timestamp: new Date().toISOString(),
      }),
    });

    if (!response.ok) {
      throw new ARPError(`Agent ${request.agent} query failed`, {
        agent: request.agent,
        status: response.status,
      });
    }

    const result: ARPResponse<T> = await response.json();

    // Cache successful responses
    if (result.success) {
      this.cache.set(cacheKey, result);
    }

    return result;
  }

  async getAgentStatus(): Promise<AgentStatus[]> {
    const response = await fetch(`${this.baseUrl}/status`, {
      headers: { 'X-ARP-Version': this.version },
    });
    return response.json();
  }

  private getCacheKey(request: ARPRequest): string {
    return `${request.agent}:${request.query}:${request.format || 'json'}`;
  }
}

// Singleton export
export const arpClient = new ARPv3Client();

// hooks/useARPData.ts
import { useQuery } from '@tanstack/react-query';
import { arpClient } from '@/lib/arp-v3-client';
import type { AgentType } from '@/lib/arp-v3-client';

interface UseARPDataOptions {
  agent: AgentType;
  query: string;
  format?: string;
  params?: Record<string, unknown>;
  enabled?: boolean;
  staleTime?: number;
}

export function useARPData<T = unknown>(options: UseARPDataOptions) {
  return useQuery({
    queryKey: ['arp', options.agent, options.query, options.format, options.params],
    queryFn: async () => {
      const response = await arpClient.query<T>({
        agent: options.agent,
        query: options.query,
        format: options.format as any,
        params: options.params,
      });
      return response;
    },
    enabled: options.enabled ?? true,
    staleTime: options.staleTime ?? 5 * 60 * 1000, // 5 minutes
    retry: 2,
    meta: {
      agent: options.agent,
    },
  });
}
